function registerOverworldContent(){
 for(const b of OW_BLOCKS)if(D[b.id]||I[b.key])throw Error('Overworld block identity conflict: '+b.key);
 for(const v of OW_ITEMS)if(I[v.key])throw Error('Overworld item identity conflict: '+v.key);
 Object.assign(A,OW_IMAGES);
 for(const b of OW_BLOCKS){
  let tex='java:minecraft:block/'+b.texture;if(!R[tex])throw Error('Missing block art: '+b.key);
  D[b.id]={name:b.name,tex,drop:b.key,time:1.4,tier:1,material:'stone'};
  item(b.key,b.name,b.id,'icon_'+b.key,{contentPack:OW_RELEASE.id});
  if(b.orientable){
   D[b.id].javaShape='decor';
   JAVA_GEOMETRY[b.id]={id:'wildblock:'+b.key,elements:[{from:[0,0,0],to:[16,16,16],faces:{down:{uv:[0,0,16,16],texture:tex,cullface:'down'},up:{uv:[0,0,16,16],texture:tex,cullface:'up'},north:{uv:[0,0,16,16],texture:tex,cullface:'north',rotation:90},south:{uv:[0,0,16,16],texture:tex,cullface:'south',rotation:270},west:{uv:[0,0,16,16],texture:tex,cullface:'west'},east:{uv:[0,0,16,16],texture:tex,cullface:'east',rotation:180}}}]};
   I[b.key].contentNote='Smelt matching dyed terracotta. Pattern orientation follows your facing on placement and is saved with the world.';
  }
 }
 for(const v of OW_ITEMS){let{key,name,texture,...extra}=v;item(key,name,0,'ow:item/'+texture,{...extra,contentPack:OW_RELEASE.id});}
 const patch=(key,props)=>{if(!I[key]?.block)throw Error('Missing base block '+key);Object.assign(D[I[key].block],props);};
 patch('java_amethyst_block',{drop:'ow_amethyst_shard',dropCount:4,tier:1,time:1.5});
 patch('java_emerald_ore',{drop:'ow_emerald',tier:3,time:3,xpDrop:3});
 patch('java_deepslate_emerald_ore',{drop:'ow_emerald',tier:3,time:4.5,xpDrop:3});
 for(const key of ['java_tuff','java_calcite','java_polished_tuff','java_tuff_bricks'])patch(key,{tier:1});
 for(const c of ["white","orange","magenta","light_blue","yellow","lime","pink","gray","light_gray","cyan","purple","blue","brown","green","red","black"])SMELT['java_'+c+'_terracotta']='ow_'+c+'_glazed_terracotta';
 Object.assign(SMELT,{java_deepslate_tiles:'java_cracked_deepslate_tiles',deepslateBricks:'java_cracked_deepslate_bricks',sandstone:'java_smooth_sandstone',java_red_sandstone:'java_smooth_red_sandstone'});
 for(const r of OW_RECIPES){if(!I[r.out]||!r.rows.every(row=>[...row].every(c=>c===' '||ingredientOptions(r.map[c]).some(k=>I[k]))))throw Error('Invalid Overworld recipe '+r.out);REC.push(r);I[r.out].overworldUpdate=true;}
 for(const k of ['java_tuff','java_calcite','java_amethyst_block','java_emerald_ore','java_deepslate_emerald_ore',...Object.keys(SMELT).filter(k=>k.endsWith('_terracotta'))])I[k].overworldUpdate=true;
 for(const k of ['java_tuff_slab','java_tuff_stairs','java_polished_tuff_slab','java_polished_tuff_stairs','java_tuff_brick_slab','java_tuff_brick_stairs'])I[k].overworldUpdate=true;
 Object.assign(EXTRA_SOURCES,{
 ow_amethyst_shard:'Mine the purple inner shell of an amethyst geode with a wooden pickaxe or better. Four shards drop per block; four shards reconstruct one block. This Wildblock adaptation uses finite geode-shell harvesting, not budding-amethyst regrowth.',
 java_amethyst_block:'Purple shells inside calcite-lined geodes in NEW terrain-v5 worlds. Drops four shards with a wooden pickaxe or better. Four shards reconstruct one block.',
 java_calcite:'White outer shells surround amethyst geodes in NEW terrain-v5 worlds. Requires a wooden pickaxe or better.',
 java_tuff:'Underground tuff pockets in NEW terrain-v5 worlds. Craft polished tuff, bricks, chiseled blocks, stairs and slabs.',
 ow_emerald:'Mine emerald ore with an iron pickaxe or better in new terrain-v5 worlds. Emeralds craft into emerald blocks; villager trading is not simulated.',
 java_emerald_ore:'Small underground emerald veins in hills of NEW terrain-v5 worlds. Requires an iron pickaxe or better.',
 java_deepslate_emerald_ore:'Deep emerald deposits below y=8 in hills of NEW terrain-v5 worlds. Requires an iron pickaxe or better.',
 ow_golden_carrot:'Surround one carrot with eight gold nuggets at a workbench. Restores six hunger. Separate saturation/status-effect mechanics are not simulated.',
 ow_pumpkin_pie:'Wildblock recipe: pumpkin, sugar and wheat in any arrangement. Restores eight hunger. Eggs are not implemented in this game.'
 });
 I.ow_pumpkin_pie.contentNote=EXTRA_SOURCES.ow_pumpkin_pie;
 I.ow_golden_carrot.contentNote=EXTRA_SOURCES.ow_golden_carrot;
 I.java_tinted_glass.contentNote='Craft using amethyst shards. Uses the existing glass renderer; Java-exact tinted-glass light blocking is not added by this update.';
 I.java_amethyst_block.contentNote=EXTRA_SOURCES.java_amethyst_block;
}
function generateOverworldDiscoveries(){
 const id=k=>I[k].block,deep=id('deepslate'),scale=W*W/16384;
 const natural=b=>b===3||b===deep;
 for(let a=0;a<Math.round(34*scale);a++){
  let x=5+Math.floor(hash(a,3101,1)*(W-10)),z=5+Math.floor(hash(a,3102,2)*(W-10)),y=6+Math.floor(hash(a,3103,3)*20);
  for(let dz=-2;dz<=2;dz++)for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)if(dx*dx+dy*dy+dz*dz<=4&&natural(get(x+dx,y+dy,z+dz)))blocks[index(x+dx,y+dy,z+dz)]=id('java_tuff');
 }
 for(let a=0;a<Math.round(8*scale);a++){
  let x,z,y,r=3,found=false;
  for(let attempt=0;attempt<96&&!found;attempt++){
   let n=a*101+attempt;x=7+Math.floor(hash(n,3201,1)*(W-14));z=7+Math.floor(hash(n,3202,2)*(W-14));y=8+Math.floor(hash(n,3203,3)*12);
   let total=0,stone=0,safe=true;
   for(let dz=-r;dz<=r;dz++)for(let dx=-r;dx<=r;dx++)if(surface[(z+dz)*W+x+dx]<y+r+3)safe=false;
   if(!safe)continue;
   for(let dz=-r;dz<=r;dz++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++)if(dx*dx+dy*dy+dz*dz<=r*r){let b=get(x+dx,y+dy,z+dz);total++;if(solid(b))stone++;if(b===15||D[b]?.liquid||b===id('java_amethyst_block')||b===id('java_calcite'))safe=false;}
   found=safe&&stone>=total*.6;
  }
  if(!found)continue;
  for(let dz=-r;dz<=r;dz++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){
   let d=dx*dx+dy*dy+dz*dz;if(d<=r*r)blocks[index(x+dx,y+dy,z+dz)]=d>6?id('java_calcite'):d>1?id('java_amethyst_block'):0;
  }
 }
 for(let a=0;a<Math.round(42*scale);a++){
  let x=4+Math.floor(hash(a,3301,1)*(W-8)),z=4+Math.floor(hash(a,3302,2)*(W-8)),h=surface[z*W+x];
  if(h<26)continue;
  let y=5+Math.floor(hash(a,3303,3)*Math.max(1,h-11));
  for(let q=0;q<3;q++){if(natural(get(x,y,z)))blocks[index(x,y,z)]=id(y<8?'java_deepslate_emerald_ore':'java_emerald_ore');x+=hash(a,q+3304,1)<.5?1:-1;}
 }
}
registerOverworldContent();
